import os

from secrets_store import read_secret

for name in ('../outside.txt', '..', os.path.abspath('outside.txt'), 'vault/../../outside.txt', ''):
    try:
        out = read_secret(name)
    except (KeyError, ValueError, OSError):
        continue
    raise AssertionError(f'read_secret({name!r}) read outside the vault: {out!r}')
